/* 5) 클라우드에만 있는 화면 META 행(사내에 없음) — 참고. 지우지 않음 */
SELECT 'SCM_ADM_API_M' AS TBL, T.API_ID
  FROM SCM_MGR.SCM_ADM_API_M T
 WHERE (API_ID LIKE 'SCP0131' || '\_%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT CAST(NULL AS VARCHAR2(4000)) API_ID FROM DUAL WHERE 1 = 0) S WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~'));
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, T.MNU_ID, T.SHT_NM, T.MNU_BTN_CD
  FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T
 WHERE (MNU_ID = 'SCP0131')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0131' MNU_ID, 'main' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0131' MNU_ID, 'main' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0131' MNU_ID, 'main' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'SCP0131' MNU_ID, 'main' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~'));
SELECT 'SCM_ADM_PROC_M' AS TBL, T.PROC_NM, T.COL_NM, T.COL_TP_CD
  FROM SCM_MGR.SCM_ADM_PROC_M T
 WHERE (PROC_NM LIKE 'PKG\_' || 'SCP0131' || '.%' ESCAPE '\')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'PKG_SCP0131.P_SCP0131_GET_SALES_SITE_PRIORITY' PROC_NM, 'divisionId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0131.P_SCP0131_GET_SALES_SITE_PRIORITY' PROC_NM, 'itemId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0131.P_SCP0131_GET_SALES_SITE_PRIORITY' PROC_NM, 'o_rc1' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_SCP0131.P_SCP0131_GET_SALES_SITE_PRIORITY' PROC_NM, 'o_result_cursor' COL_NM, 'OUT' COL_TP_CD FROM DUAL
