SELECT 'SCM_MST_SHEET_COLUMNS' AS TBL, T.PROGRAM_ID, T.SHEET_NAME, T.COLUMN_NAME
  FROM SCM_MGR.SCM_MST_SHEET_COLUMNS T
 WHERE (PROGRAM_ID = 'SCP0131')
   AND NOT EXISTS (SELECT 1 FROM (SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'CREATED_BY' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'CREATION_DATE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'DIVISION_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'FROM_YYYYMMDD' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'ITEM_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'LAST_UPDATED_BY' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'LAST_UPDATE_DATE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'OPMZ_PLAN_GR_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'PRE_KEY_VALUES' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'PRIO_RANK' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'SCM_SITE_ID' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'TO_YYYYMMDD' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'VALID_YN' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'SCP0131' PROGRAM_ID, 'Sales Site Priority' SHEET_NAME, 'VALUE_DESCRIPTION' COLUMN_NAME FROM DUAL) S WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~') AND NVL(TO_CHAR(T.COLUMN_NAME), '~') = NVL(TO_CHAR(S.COLUMN_NAME), '~'));
SELECT 'SCM_MST_SHEET_MEASURE' AS TBL, T.PROGRAM_ID, T.SHEET_NAME
  FROM SCM_MGR.SCM_MST_SHEET_MEASURE T
 WHERE (PROGRAM_ID = 'SCP0131')
   AND NOT EXISTS (SELECT 1 FROM (SELECT CAST(NULL AS VARCHAR2(4000)) PROGRAM_ID, CAST(NULL AS VARCHAR2(4000)) SHEET_NAME FROM DUAL WHERE 1 = 0) S WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~'));
